INSERT INTO inventory_movements(product_id,movement_type,quantity,reason,reference_type,reference_id) SELECT p.id,'opening',p.quantity,'Seed opening stock','seed',p.id FROM products p WHERE NOT EXISTS(SELECT 1 FROM inventory_movements m WHERE m.product_id=p.id);
